const item = $input.first().json;
const path = String(item.path ?? item.fileName ?? item.name ?? '').trim();
if (!path) {
  throw new Error('El trigger no devolvió ruta de archivo. Revisa Local File Trigger.');
}

const base = path.split(/[/\\]/).pop() || 'archivo';
const destDir = 'C:\\Users\\chuwi\\n8n-procesados';
const dest = `${destDir}\\${base}`;

return [
  {
    json: {
      sourcePath: path,
      fileName: base,
      destPath: dest,
      destDir,
      ahora: new Date().toLocaleString('es-ES'),
    },
  },
];

